function icon(name, cls = '') { return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.flag}"/></svg>`; }
function button(label, action, style = '', value = '', extra = '') { return `<button class="btn ${style}" data-action="${action}" ${value !== '' ? `data-value="${escapeHtml(value)}"` : ''} ${extra}>${label}</button>`; }
function brand() { return `<button class="brand" data-action="nav" data-value="race" aria-label="Beat My Track, go to Race"><span>BEAT <i class="speed-lines"></i></span><span><em>MY</em> TRACK</span></button>`; }
const defaultSettings = {steering:'Buttons',camera:'Overhead',zoom:30,shadows:'Auto',resolution:'Auto',antialias:'Auto',music:70,effects:85,reduceMotion:false,largeText:false};
