 track:v=>{state.track=Number(v);render();},bookmark:v=>{const i=Number(v);state.bookmarks.has(i)?state.bookmarks.delete(i):state.bookmarks.add(i);persistGarage();render();toast(state.bookmarks.has(i)?'Circuit bookmarked.':'Bookmark removed.');},random:()=>{state.track=(state.track+1)%tracks.length;state.query='';state.filter='all';render();},filters:()=>showModal('filters'),
 'saved-filter':()=>{state.filter=state.filter==='saved'?'all':'saved';state.query='';render();},'filter-reset':()=>{state.filter='all';closeModal();render();},'filter-apply':()=>{state.filter=$('#filter-biome').value;closeModal();render();},'clear-search':()=>{state.query='';state.filter='all';state.scenario='online';render();},
